const likesMoney=n=>'₱'+Number(n).toLocaleString('en-PH',{minimumFractionDigits:2,maximumFractionDigits:2});
const likesEscape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
const likesCategoryNames={
 'pet-supplies':'Pet Supplies','electronics-and-gadgets':'Electronics & Gadgets','women-s-apparel':"Women's Apparel",
 'men-s-apparel':"Men's Apparel",'kids-and-baby':'Kids & Baby','home-and-garden':'Home & Garden','sports-and-outdoors':'Sports & Outdoors',
 'health-and-beauty':'Health & Beauty','books-and-media':'Books & Media','jewelry-and-watches':'Jewelry & Watches',
 'food-and-gourmet':'Foods & Gourmet','furniture-and-office-equipment':'Furniture & Office'
};
const likesFilterGroups=[
 {key:'all',label:'All liked items',icon:'apps'},
 {key:'electronics',label:'Electronics',slugs:['electronics-and-gadgets']},
 {key:'fashion',label:'Fashion',slugs:['women-s-apparel','men-s-apparel']},
 {key:'home-living',label:'Home & Living',slugs:['home-and-garden','furniture-and-office-equipment']},
 {key:'beauty',label:'Beauty',slugs:['health-and-beauty']},
 {key:'sports',label:'Sports & Outdoors',slugs:['sports-and-outdoors']},
 {key:'more',label:'More',slugs:['pet-supplies','kids-and-baby','books-and-media','jewelry-and-watches','food-and-gourmet'],more:true}
];
const likesMoreGroups=[
 {key:'pet-supplies',label:'Pet Supplies'},{key:'kids-and-baby',label:'Kids & Baby'},
 {key:'books-and-media',label:'Books & Media'},{key:'jewelry-and-watches',label:'Jewelry & Watches'},
 {key:'food-and-gourmet',label:'Foods & Gourmet'}
];
let likesCategory='all',likesSort='recent';
function normalizeLikeKey(value){const key=String(value||'');const legacy=key.match(/^home-(.+)-(\d+)$/);return legacy?`${legacy[1]}:${legacy[2]}`:key}
function getLikedKeys(){try{const x=JSON.parse(localStorage.getItem(LIKES_KEY)||'[]');if(!Array.isArray(x))return[];const normalized=[...new Set(x.map(normalizeLikeKey).filter(Boolean))];if(JSON.stringify(normalized)!==JSON.stringify(x))localStorage.setItem(LIKES_KEY,JSON.stringify(normalized));return normalized}catch{return[]}}
function saveLikedKeys(keys){try{localStorage.setItem(LIKES_KEY,JSON.stringify([...new Set(keys)]))}catch{}}
function likedProducts(){const byKey=new Map(likesCatalog.map(product=>[product.key,product]));return getLikedKeys().map(key=>byKey.get(key)).filter(Boolean)}
function likeCategoryKey(product){return String(product.key||'').split(':')[0]}
function likeCategoryGroup(product){const key=likeCategoryKey(product);return likesFilterGroups.find(group=>!group.more&&group.slugs?.includes(key))}
function likeCategoryName(product){return likeCategoryGroup(product)?.label||likesCategoryNames[likeCategoryKey(product)]||product.category||'Bearly products'}
function likeFilterMatches(product,filter){if(filter==='all')return true;const group=likesFilterGroups.find(item=>item.key===filter);return group?.slugs?.includes(likeCategoryKey(product))||likeCategoryKey(product)===filter}
function likeFilterActive(group){if(group.key==='all')return likesCategory==='all';if(group.more)return group.slugs.includes(likesCategory);return likesCategory===group.key}
function likeSeed(product){let seed=0;for(const char of String(product.key||'')){seed=(seed*31+char.charCodeAt(0))>>>0}return seed}
function likeSold(product){const value=180+(likeSeed(product)%4621);return value>=1000?`${(value/1000).toFixed(1)}k`:String(value)}
function likeReviews(product){const value=320+(likeSeed(product)%1780);return value>=1000?`${(value/1000).toFixed(1)}k`:String(value)}
function likeRating(product){const rating=Number(product.rating);return Number.isFinite(rating)&&rating>0?Math.min(5,rating).toFixed(1):'4.5'}
function sortLikedProducts(items){const rows=[...items];if(likesSort==='price-low')rows.sort((a,b)=>Number(a.price||0)-Number(b.price||0));if(likesSort==='price-high')rows.sort((a,b)=>Number(b.price||0)-Number(a.price||0));if(likesSort==='name')rows.sort((a,b)=>String(a.name).localeCompare(String(b.name)));if(likesSort==='rating')rows.sort((a,b)=>Number(b.rating||0)-Number(a.rating||0)||String(a.name).localeCompare(String(b.name)));return rows}
function renderLikeTabs(){const tabs=document.getElementById('likes-category-tabs');if(!tabs)return;const visible=likesFilterGroups.slice(0,6);tabs.innerHTML=visible.map(group=>`<button type="button" class="likes-category-tab${likeFilterActive(group)?' is-active':''}${group.key==='all'?' likes-all-tab':''}" data-likes-category="${likesEscape(group.key)}" role="tab" aria-selected="${likeFilterActive(group)?'true':'false'}">${group.icon?`<span class="material-symbols-outlined likes-tab-icon" aria-hidden="true">${group.icon}</span>`:''}${likesEscape(group.label)}</button>`).join('')+`<span class="likes-more-wrap"><button type="button" class="likes-category-tab likes-more-toggle${likeFilterActive(likesFilterGroups[6])?' is-active':''}" data-likes-more-toggle aria-expanded="false">More<span class="material-symbols-outlined likes-tab-chevron" aria-hidden="true">expand_more</span></button><span class="likes-more-menu" hidden>${likesMoreGroups.map(group=>`<button type="button" data-likes-category="${group.key}" role="menuitem">${likesEscape(group.label)}</button>`).join('')}</span></span>`}
function recommendationProducts(items){const saved=new Set(items.map(product=>product.key));const picks=[];for(const category of ['electronics-and-gadgets','health-and-beauty','women-s-apparel','home-and-garden']){const product=likesCatalog.find(item=>likeCategoryKey(item)===category&&!saved.has(item.key));if(product)picks.push(product)}for(const product of likesCatalog){if(picks.length>=4)break;if(!saved.has(product.key)&&!picks.some(item=>item.key===product.key))picks.push(product)}return picks.slice(0,4)}
function renderRecommendations(items){const section=document.getElementById('likes-recommendations'),grid=document.getElementById('likes-recommendation-grid');if(!section||!grid)return;const recommendations=recommendationProducts(items);section.hidden=recommendations.length===0;grid.innerHTML=recommendations.map(product=>`<article class="like-recommendation-card"><div class="like-recommendation-image"><img src="${likesEscape(product.image||'/images/bearly-logo.png')}" alt="${likesEscape(product.name)}" loading="lazy"></div><div class="like-recommendation-copy"><span>${likesEscape(likeCategoryName(product))}</span><h3 title="${likesEscape(product.name)}">${likesEscape(product.name)}</h3><div><b><span class="material-symbols-outlined" aria-hidden="true">star</span>${likeRating(product)}</b><small>(${likesEscape(likeReviews(product))})</small></div><strong>${likesMoney(product.price)}</strong></div><button type="button" class="like-recommend-like" data-recommend-like="${likesEscape(product.key)}" aria-label="Like ${likesEscape(product.name)}"><span class="material-symbols-outlined" aria-hidden="true">favorite_border</span></button></article>`).join('')}
function renderMyLikes(){
 const grid=document.getElementById('likes-grid'),empty=document.getElementById('likes-empty'),count=document.getElementById('likes-count'),navCount=document.getElementById('likes-nav-count');
 if(!grid)return;
 const allItems=likedProducts(),items=sortLikedProducts(allItems.filter(product=>likeFilterMatches(product,likesCategory)));
 renderLikeTabs();
 if(count)count.textContent=`${allItems.length} liked item${allItems.length===1?'':'s'}`;
 if(navCount){navCount.textContent=String(allItems.length);navCount.hidden=allItems.length===0}
 grid.hidden=items.length===0;grid.innerHTML=items.map(product=>`<article class="like-card" data-like-card data-like-key="${likesEscape(product.key)}"><div class="like-image"><img src="${likesEscape(product.image||'/images/bearly-logo.png')}" alt="${likesEscape(product.name)}" loading="lazy"><button type="button" class="like-remove" data-like-key="${likesEscape(product.key)}" aria-label="Remove ${likesEscape(product.name)} from My Likes"><span class="material-symbols-outlined" aria-hidden="true">favorite</span></button></div><div class="like-copy"><span class="like-category">${likesEscape(likeCategoryName(product))}</span><h3 title="${likesEscape(product.name)}">${likesEscape(product.name)}</h3><div class="like-meta"><span class="like-rating"><span class="material-symbols-outlined" aria-hidden="true">star</span>${likeRating(product)}</span><span class="like-reviews">(${likesEscape(likeReviews(product))} reviews)</span><i aria-hidden="true">•</i><span>${likesEscape(likeSold(product))} sold</span></div><strong class="like-price">${likesMoney(product.price)}</strong><button type="button" class="like-cart" data-like-key="${likesEscape(product.key)}"><span class="material-symbols-outlined" aria-hidden="true">shopping_cart</span><span class="like-cart-label">Add to Cart</span></button></div></article>`).join('');
 const hasItems=items.length>0;empty.hidden=hasItems;
 const emptyTitle=document.getElementById('likes-empty-title'),emptyCopy=document.getElementById('likes-empty-copy');
 if(!hasItems&&emptyTitle)emptyTitle.textContent=likesCategory==='all'?'No liked products yet':'No liked products in this category';
 if(!hasItems&&emptyCopy)emptyCopy.textContent=likesCategory==='all'?'Tap the heart on a product and it will appear here automatically.':'Try another category or tap the heart on more products.';
 renderRecommendations(allItems);
}
function saveLikeCart(product,button){const cartKey=window.bearlyStorageKey?.('preview-cart')||'bearly-preview-cart-v1';let items=[];try{const x=JSON.parse(localStorage.getItem(cartKey)||'[]');items=Array.isArray(x)?x:[]}catch{}const key='wishlist-'+product.key,existing=items.find(item=>item.key===key);if(existing)existing.quantity=Number(existing.quantity||1)+1;else items.push({key,product_id:product.key,name:product.name,price:Number(product.price||0),color:'',size:'',quantity:1,image:product.image||'',category:product.category||'',seller_name:'Bearly Seller',frontend_preview:true});try{localStorage.setItem(cartKey,JSON.stringify(items));window.dispatchEvent(new CustomEvent('bearly:cart-changed'))}catch{}if(button){button.classList.add('is-added');const label=button.querySelector('.like-cart-label');if(label)label.textContent='Added to Cart';window.setTimeout(()=>{button.classList.remove('is-added');if(label)label.textContent='Add to Cart'},1100)}}
function initLikesControls(){const tabs=document.getElementById('likes-category-tabs');if(!tabs||window.bearlyLikesControlsInitialized)return;window.bearlyLikesControlsInitialized=true;const sort=document.getElementById('likes-sort');tabs.addEventListener('click',event=>{const more=event.target.closest('[data-likes-more-toggle]');if(more){const menu=tabs.querySelector('.likes-more-menu');if(menu)menu.hidden=!menu.hidden;more.setAttribute('aria-expanded',String(menu&&!menu.hidden));return}const tab=event.target.closest('[data-likes-category]');if(!tab)return;likesCategory=tab.dataset.likesCategory||'all';const menu=tabs.querySelector('.likes-more-menu');if(menu)menu.hidden=true;renderMyLikes()});sort?.addEventListener('change',()=>{likesSort=sort.value||'recent';renderMyLikes()});document.addEventListener('click',event=>{if(!event.target.closest('.likes-more-wrap')){const menu=tabs.querySelector('.likes-more-menu');if(menu)menu.hidden=true}const remove=event.target.closest('.like-remove');if(remove){saveLikedKeys(getLikedKeys().filter(key=>key!==remove.dataset.likeKey));renderMyLikes();return}const recommendation=event.target.closest('[data-recommend-like]');if(recommendation){saveLikedKeys([...getLikedKeys(),recommendation.dataset.recommendLike]);renderMyLikes();return}const cart=event.target.closest('.like-cart');if(cart){const product=likesCatalog.find(item=>item.key===cart.dataset.likeKey);if(product)saveLikeCart(product,cart)}});window.renderMyLikes=renderMyLikes;renderMyLikes()}
window.addEventListener('storage',event=>{if(event.key===LIKES_KEY)renderMyLikes()});
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',initLikesControls);else initLikesControls();
